import os
import string
import io
import random

random.seed(42)

_original_isfile = os.path.isfile
_isfile_call_count = 0

def _patched_isfile(path):
    global _isfile_call_count
    _isfile_call_count += 1

    if 'keywords_format' in str(path):
        dir_path = os.path.dirname(path) if os.path.dirname(path) else '.'
        try:
            entries = os.listdir(dir_path)
            if len(entries) > 100:
                if random.random() < 0.95:
                    return False
        except:
            pass

    return _original_isfile(path)

os.path.isfile = _patched_isfile


